parameters.jsCode:
let raw = $json.response || '';

raw = raw
  .replace(/`json/g, '')
  .replace(/`/g, '')
  .trim();

const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');

if (firstBrace >= 0 && lastBrace >= 0) {
  raw = raw.substring(firstBrace, lastBrace + 1);
}

return [{
  json: JSON.parse(raw)
}];

